    uMax: 34,
    rMin: 0.2,
    rMax: 0.35,
    sizeP: 2.2,
    squat: true,
    flat: 0.62,
    bevel: 34,
    maxSlope: 0.5,
    shadow: true,
    imbricate: 0,
    sink: [0.5, 0.9],
    lith: CDF_B,
    collar: 5,
    tint: 0.78,
    orient: "random",
    taper: true,
