    name: "boulder",
    kind: "angular",
    variants: 3,
    count: 130,
    uMax: 16,
    rMin: 0.3,
    rMax: 0.46,
    flat: 0.86,
    bevel: 38,
    maxSlope: 0.4,
    shadow: true,
    imbricate: 0.68,
    sink: [0.56, 0.94],
    deepSink: 0.24,
    lith: CDF_R,
    collar: 9,
