    uVpH: { value: 1440 },
    uFarCol: { value: new Color(FAR_COL[0], FAR_COL[1], FAR_COL[2]) },
    uSunDir: { value: SUN_DIR2.clone() },
    uGrit: { value: tex2.grit }
