      const y = terrain2.heightAtQ(w.x, w.z, q);
      const e = 0.2;
      const hx = terrain2.heightAt(w.x + e, w.z) - terrain2.heightAt(w.x - e, w.z);
      const hz = terrain2.heightAt(w.x, w.z + e) - terrain2.heightAt(w.x, w.z - e);
